contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: put some ETH, then collect some amount; finally assert balance decreased by collected amount.
    // params: amountPut > MinSum, amountCollect <= amountPut
    function run(uint amountPut, uint amountCollect) public payable {
        // require this test harness has enough balance to forward
        require(address(this).balance >= amountPut, "insufficient harness balance");
        // preconditions to make calls meaningful
        require(amountPut >= 1 ether, "amountPut must be >= MinSum");
        require(amountCollect > 0 && amountCollect <= amountPut, "collect amount invalid");

        // get initial recorded balance for this address in c
        uint before = c.Acc(address(this)).balance;

        // 1) Put funds (will set unlockTime to >= block.timestamp)
        c.Put{value: amountPut}(block.timestamp);

        // 2) Advance conditions: ensure unlock time passed by using zero unlock time in Put above (block.timestamp)
        // Now try to Collect amountCollect; on P this will succeed and reduce recorded balance by amountCollect.
        c.Collect(amountCollect);

        uint after = c.Acc(address(this)).balance;

        // The distinguishing property: after balance equals before + amountPut - amountCollect.
        // On P the Collect call succeeds and decreases balance by amountCollect, so this holds for all inputs meeting preconditions.
        // On M (broken modifier that never unlocks) the second call to Collect would revert (or future collects fail), violating the general rule about observable balance decrease.
        assert(after == before + amountPut - amountCollect);
    }

    // Allow funding this contract for tests
    receive() external payable {}
}

